# An argument's value is gram.y's expr: '=' names an argument only after a
# symbol, a string or NULL, and is no assignment there (f(NA = 1) is a
# syntax error); bodies, parentheses, braces and unary ? take an assignment
p <- tryCatch(parse(text = 'f(NA = 1)'), error = function(e) conditionMessage(e)); if (is.character(p)) cat('NA: ERR', gsub('\n', ' | ', p), '\n') else { cat('NA: OK names=', deparse(names(p[[1]])), ' deparse=', deparse(p[[1]]), '\n') }
