for (t in c("f(x = a ? b)", "f(x = a ? b = 1)", "f(a ? b)", "f(x = ?y = 1)", "f(x = function() y = 1)")) { p <- tryCatch(parse(text = t), error = function(e) conditionMessage(e)); cat(t, ": ", if (is.character(p)) gsub("\n", " | ", p) else deparse(p[[1]]), "\n") }
for (t in c("if (a = b) c", "f(if (a = b) c)", "while (a = b) c", "for (i in a = b) c", "if (a ? b) c", "for (i in a ? b) c", "function(x = a ? b) x", "function(x = y = 1) x", "function(x = ?y = 1) x", "function(x = (y = 1)) x", "if ((a = b)) c")) { p <- tryCatch(parse(text = t), error = function(e) conditionMessage(e)); cat(t, ": ", if (is.character(p)) gsub("\n", " | ", p) else deparse(p[[1]]), "\n") }
